CREATE OR REPLACE FUNCTION private.ledger_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if tg_op = 'DELETE' then raise exception 'Ledger entries are never deleted.'; end if;
  if new.amount is distinct from old.amount or new.kind is distinct from old.kind or new.store_id is distinct from old.store_id
     or new.order_id is distinct from old.order_id or new.seller_order_id is distinct from old.seller_order_id or new.currency is distinct from old.currency then
    raise exception 'Ledger amounts are never edited; add a reversing entry.';
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.chat_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if new.kind='text' and new.body ~* '(code|otp|pin)' and new.body ~ '(^|\D)\d{4}(\D|$)' then
    new.body := regexp_replace(new.body,'(^|\D)\d{4}(\D|$)','\1••••\2','g');
    new.meta := new.meta || '{"redacted":true}'::jsonb;
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.chat_triage()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare c public.conversations%rowtype; r public.support_rules%rowtype; v_tags text[]:='{}'; v_prio int:=0; v_esc text; v_mins int;
        v_responder boolean; v_customer boolean; o public.orders%rowtype; v_so text; v_nm text;
begin
  select * into c from public.conversations where id=new.conversation_id;
  if not found then return new; end if;
  if new.kind in ('text','system','order_card') then
    update public.conversation_members set unread=unread+1 where conversation_id=new.conversation_id and user_id is distinct from new.sender_id;
  end if;
  if new.kind='note' then return new; end if;
  update public.conversations set last_message_at=new.created_at,
    last_preview=case when new.kind in ('text','order_card') then left(new.body,80) else last_preview end,
    status=case when status='resolved' and new.kind='text' then 'open' else status end,
    resolved_at=case when status='resolved' and new.kind='text' then null else resolved_at end,
    admin_unread=case when new.kind='text' and new.sender_role not in ('admin','system') then true else admin_unread end
  where id=new.conversation_id;
  if new.kind<>'text' then return new; end if;

  v_responder := new.sender_role='admin' or (c.kind='store' and new.sender_role='seller') or (c.kind='admin_user' and new.sender_role<>'admin');
  v_customer := not v_responder and new.sender_role<>'system';
  if v_responder then
    update public.conversations set sla_due_at=null, first_reply_at=coalesce(first_reply_at,new.created_at) where id=c.id;
  elsif v_customer then
    v_mins := case when c.kind='store' then coalesce((select (value->>'seller_reply_minutes')::int from public.support_settings where key='sla'),30)
                   when c.kind in ('support','seller_admin') then public.support_sla_minutes(c.tier) else null end;
    if v_mins is not null then update public.conversations set sla_due_at=coalesce(sla_due_at, now()+make_interval(mins=>v_mins)) where id=c.id; end if;
  end if;

  if new.meta ? 'redacted' then
    insert into public.messages(conversation_id,sender_role,kind,body,meta)
    values(new.conversation_id,'system','shield','For your safety we hid a 4-digit number. Never share your delivery code in chat. Give it only when your items arrive.','{"rule":"code"}'::jsonb);
    v_tags := array_append(v_tags,'code-shared'); v_prio := greatest(v_prio,1);
  end if;

  if new.sender_role not in ('admin','system') then
    for r in select * from public.support_rules where active and c.kind=any(applies_to) and new.body ~* pattern order by priority desc, id loop
      if r.tag is not null then v_tags := array_append(v_tags,r.tag); end if;
      v_prio := greatest(v_prio,r.priority);
      if r.action='escalate' and v_esc is null then v_esc := coalesce(r.reason,r.name); end if;
      if r.action='shield' and r.reply is not null and not exists(select 1 from public.messages where conversation_id=c.id and kind='shield' and meta->>'rule'=r.id::text and created_at>now()-interval '10 minutes') then
        insert into public.messages(conversation_id,sender_role,kind,body,meta) values(c.id,'system','shield',r.reply,jsonb_build_object('rule',r.id::text));
      end if;
    end loop;
  end if;
  if cardinality(v_tags)>0 or v_prio>0 then
    update public.conversations set tags=(select coalesce(array_agg(distinct t),'{}') from unnest(v_tags||conversations.tags) t), priority=greatest(priority,v_prio) where id=c.id;
  end if;
  if v_esc is not null then perform public.chat_escalate_core(c.id,v_esc,greatest(v_prio,1)); end if;

  if c.order_id is not null and new.sender_role in ('buyer','user') and new.body ~* '(where is|where.s my|track|order status|when will|how long|eta)' then
    select * into o from public.orders where id=c.order_id;
    if found then
      select status into v_so from public.seller_orders where order_id=c.order_id and (c.store_id is null or store_id=c.store_id) limit 1;
      insert into public.messages(conversation_id,sender_role,kind,body,meta)
      values(c.id,'system','order_card','Order '||coalesce(o.ref,left(o.id,8))||': '||coalesce(o.status,'processing')||case when v_so is not null then ' (seller: '||v_so||')' else '' end,
        jsonb_build_object('order_id',o.id,'status',o.status,'seller_status',v_so,'payment',o.payment_status));
    end if;
  end if;

  v_nm := case new.sender_role when 'admin' then 'Everneed Support' else coalesce((select name from public.profiles where id=new.sender_id),'New message') end;
  insert into public.notifications(id,user_id,kind,title,body,data)
  select gen_random_uuid()::text, m.user_id,'message',v_nm,left(new.body,120),jsonb_build_object('conversation',new.conversation_id,'kind',c.kind)
  from public.conversation_members m where m.conversation_id=new.conversation_id and m.user_id is distinct from new.sender_id and not m.muted;
  return new;
end $function$

CREATE OR REPLACE FUNCTION private.orders_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if new.status is not distinct from old.status then return new; end if;
  if not private.order_step_ok(old.status, new.status) then
    raise exception 'An order cannot move from % to %.', old.status, new.status;
  end if;
  if not (coalesce(current_setting('app.order_bypass', true), '') = '1' and current_user not in ('authenticated', 'anon')) then
    if new.status = 'paid' and old.payment_status <> 'paid' then raise exception 'Payments are confirmed with confirm_payment().'; end if;
    if new.status in ('shipped', 'out_for_delivery', 'delivered') and exists (
      select 1 from public.seller_orders so join public.stores s on s.id = so.store_id where so.order_id = new.id and not s.is_official) then
      raise exception 'Marketplace orders are dispatched and delivered through the delivery functions.';
    end if;
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION private.products_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare st text; trusted boolean; lim int; used int;
begin
  if new.store_id is null then new.store_id := (select id from public.stores where is_official limit 1); end if;
  if private.is_privileged() then return new; end if;
  select status into st from public.stores where id = new.store_id;
  if tg_op = 'INSERT' then
    if new.status not in ('draft', 'pending_review') then raise exception 'New products start as draft or pending review.'; end if;
    select pl.product_limit into lim from public.store_subscriptions ss join public.store_plans pl on pl.id = ss.plan_id where ss.store_id = new.store_id;
    if lim is not null then
      select count(*) into used from public.products where store_id = new.store_id and status <> 'archived';
      if used >= lim then raise exception 'Your plan allows % products. Archive some or upgrade your plan to add more.', lim; end if;
    end if;
  else
    if new.store_id is distinct from old.store_id then raise exception 'A product cannot move to another store.'; end if;
    if new.status = 'published' and old.status is distinct from 'published' then raise exception 'Only the EverNeed team publishes products.'; end if;
    if new.status = 'rejected' and old.status is distinct from 'rejected' then raise exception 'Only the EverNeed team rejects products.'; end if;
    if old.status = 'published' and new.status = 'published'
       and (new.name is distinct from old.name or new.descr is distinct from old.descr or new.images is distinct from old.images or new.img is distinct from old.img) then
      new.status := 'pending_review';
    end if;
    if old.status = 'archived' and new.status <> 'archived' then
      select pl.product_limit into lim from public.store_subscriptions ss join public.store_plans pl on pl.id = ss.plan_id where ss.store_id = new.store_id;
      if lim is not null then
        select count(*) into used from public.products where store_id = new.store_id and status <> 'archived';
        if used >= lim then raise exception 'Your plan allows % products. Archive some or upgrade your plan to restore this one.', lim; end if;
      end if;
    end if;
  end if;
  if new.status = 'pending_review' then
    if st is distinct from 'approved' then raise exception 'Your store must be approved before products go for review.'; end if;
    select sp.trusted into trusted from public.store_private sp where sp.store_id = new.store_id;
    if coalesce(trusted, false) and coalesce((select (data->>'auto_approve_trusted')::boolean from public.settings where id = 'policy'), false) then
      new.status := 'published';
    end if;
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION private.seller_orders_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if new.status is not distinct from old.status then return new; end if;
  if coalesce(current_setting('app.order_bypass', true), '') = '1' and current_user not in ('authenticated', 'anon') then return new; end if;
  if not private.so_step_ok(old.status, new.status, (select route from public.orders where id = new.order_id)) then
    raise exception 'A seller order cannot move from % to %.', old.status, new.status;
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION private.store_private_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if not private.is_privileged() then
    if tg_op = 'INSERT' then
      if new.status_note is not null or new.commission_override is not null or new.trusted then raise exception 'Not allowed.'; end if;
    elsif new.status_note is distinct from old.status_note or new.commission_override is distinct from old.commission_override or new.trusted is distinct from old.trusted then
      raise exception 'That setting is managed by the EverNeed team.';
    end if;
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION private.stores_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare base text; n int := 0;
begin
  if tg_op = 'INSERT' then
    base := private.slugify(coalesce(new.slug, new.name)); new.slug := base;
    while exists (select 1 from public.stores where slug = new.slug) loop n := n + 1; new.slug := base || '-' || n; end loop;
    if not private.is_privileged() then
      if new.status not in ('draft', 'pending') then raise exception 'A new store starts as draft or pending.'; end if;
      new.is_official := false; new.is_demo := false; new.approved_at := null;
    end if;
    return new;
  end if;
  if not private.is_privileged() then
    if new.owner_id is distinct from old.owner_id or new.is_official is distinct from old.is_official or new.is_demo is distinct from old.is_demo
       or new.approved_at is distinct from old.approved_at or new.slug is distinct from old.slug then
      raise exception 'That store field cannot be changed from the app.';
    end if;
    if new.status is distinct from old.status and not (old.status in ('draft', 'rejected') and new.status = 'pending') then
      raise exception 'Store status is changed by the EverNeed team.';
    end if;
  end if;
  return new;
end $function$
